THOUGHT: The core database foundation now compiles. I’ll add the HTTP API covering authentication, workspaces/channels, messages, reactions, DMs, files, groups, profiles, slash commands, pagination, and a polling WebSocket so the staged checks can exercise the implemented domain behavior.

```mswea_bash_command
cat > /app/server.py <<'PY'
import asyncio,json,os,argparse,re,urllib.parse
from aiohttp import web,WSMsgType
import core
def out(d,status=200): return web.json_response(d,status=status)
def err(s,m): return out({'error':m},s)
async def body(r):
 try:return await r.json()
 except:return None
def auth(r):
 h=r.headers.get('Authorization','')
 return core.user_for_token(h[7:] if h.startswith('Bearer ') else None)
def uid(r):
 u=auth(r); return u['id'] if u else None
def workspace_channels(w,u,include=False):
 c=core.connect(); a=[]
 for x in c.execute('SELECT * FROM channels WHERE workspace_id=? AND (? OR is_archived=0) ORDER BY id',(w['id'],include)):
  if core.can_read_channel(u,x):a.append(core.channel_to_json(x))
 c.close();return a
async def health(r): return out({'status':'ok','node_id':r.app['node']})
async def register(r):
 d=await body(r)
 if not isinstance(d,dict) or not isinstance(d.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',d.get('username','')) or not isinstance(d.get('password'),str) or len(d['password'])<8:return err(400,'invalid')
 with core.tx() as c:
  try:
   c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),d.get('display_name') or d['username']))
   u=c.execute('SELECT * FROM users WHERE id=last_insert_rowid()').fetchone(); t=core.issue_token(c,u['id'])
  except: return err(409,'duplicate')
 return out({'user':core.user_to_json(u),'token':t},201)
async def login(r):
 d=await body(r);c=core.connect();u=c.execute('SELECT * FROM users WHERE username=?',(d.get('username') if isinstance(d,dict) else '',)).fetchone();c.close()
 if not u or not core.verify_password(d.get('password',''),u['password']):return err(401,'invalid credentials')
 with core.tx() as c:t=core.issue_token(c,u['id'])
 return out({'user':core.user_to_json(u),'token':t})
async def me(r):
 u=auth(r);return out({'user':core.user_to_json(u)}) if u else err(401,'unauthorized')
async def workspaces(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 c=core.connect();a=[core.workspace_to_json(x) for x in c.execute('SELECT w.* FROM workspaces w JOIN wmembers m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],))];c.close();return out({'workspaces':a})
async def create_workspace(r):
 u=auth(r);d=await body(r)
 if not u:return err(401,'unauthorized')
 if not isinstance(d,dict) or not re.fullmatch(r'[a-z0-9-]{2,32}',str(d.get('slug',''))) or not isinstance(d.get('name'),str):return err(400,'invalid')
 with core.tx() as c:
  try:
   c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(d['slug'],d['name'],u['id']));w=c.execute('SELECT * FROM workspaces WHERE id=last_insert_rowid()').fetchone()
  except:return err(409,'duplicate')
  c.execute("INSERT INTO channels(workspace_id,name) VALUES(?, 'general')",(w['id'],));ch=c.execute('SELECT * FROM channels WHERE id=last_insert_rowid()').fetchone();core.add_workspace_member(c,w['id'],u['id'],'owner')
 return out({'workspace':core.workspace_to_json(w),'general_channel':core.channel_to_json(ch)},201)
async def workspace(r):
 u=auth(r);w=core.get_workspace(r.match_info['slug'])
 if not u:return err(401,'unauthorized')
 if not w or not core.member_role(w['id'],u['id']):return err(404,'not found')
 return out({'workspace':core.workspace_to_json(w),'channels':workspace_channels(w,u['id'])})
async def create_channel(r):
 u=auth(r);w=core.get_workspace(r.match_info['slug']);d=await body(r)
 if not u:return err(401,'unauthorized')
 if not w:return err(404,'not found')
 if not core.member_role(w['id'],u['id']):return err(403,'forbidden')
 if not isinstance(d,dict) or not re.fullmatch(r'[a-z0-9-]{1,32}',str(d.get('name',''))):return err(400,'invalid')
 with core.tx() as c:
  try:c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],d['name'],int(bool(d.get('is_private'))),d.get('topic','')));ch=c.execute('SELECT * FROM channels WHERE id=last_insert_rowid()').fetchone();core.add_channel_member(c,ch['id'],u['id'])
  except:return err(409,'duplicate')
 return out({'channel':core.channel_to_json(ch)},201)
async def join(r):
 u=auth(r);ch=core.get_channel(r.match_info['id'])
 if not u:return err(401,'unauthorized')
 if not ch:return err(404,'not found')
 with core.tx() as c:
  core.add_channel_member(c,ch['id'],u['id'])
  if ch['workspace_id']:core.add_workspace_member(c,ch['workspace_id'],u['id'])
 return out({'channel':core.channel_to_json(ch)})
async def post(r):
 u=auth(r);ch=core.get_channel(r.match_info['id']);d=await body(r)
 if not u:return err(401,'unauthorized')
 if not ch:return err(404,'not found')
 if not core.can_read_channel(u['id'],ch):return err(403,'forbidden')
 if ch['is_archived']:return err(423,'archived')
 if not isinstance(d,dict) or not isinstance(d.get('body'),str) or not d['body'].strip():return err(400,'empty')
 b=d['body']
 if b.startswith('/') and not b.startswith('//'):
  p=b.split(' ',1);cmd=p[0];text=p[1] if len(p)>1 else ''
  if cmd=='/shrug':b=(text+' ' if text else '')+'¯\\_(ツ)_/¯'
  elif cmd=='/me' and not text:return err(400,'text required')
  elif cmd=='/me':b=b
  elif cmd=='/topic':
   with core.tx() as c:c.execute('UPDATE channels SET topic=? WHERE id=?',(text,ch['id']));ch=core.get_channel(ch['id'])
   return out({'message':None,'channel':core.channel_to_json(ch)},201)
  elif cmd in ('/archive','/unarchive'):
   with core.tx() as c:c.execute('UPDATE channels SET is_archived=? WHERE id=?',(cmd=='/archive',ch['id']));ch=core.get_channel(ch['id'])
   return out({'message':None,'channel':core.channel_to_json(ch)},201)
  else:return err(400,'unknown command')
 if b.startswith('//'):b=b[1:]
 with core.tx() as c:
  c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(ch['id'],u['id'],b,d.get('parent_id'),core.now_iso()));m=c.execute('SELECT * FROM messages WHERE id=last_insert_rowid()').fetchone();core.emit_event(c,ch['id'],'message.reply' if d.get('parent_id') else 'message.created',{'message':core.message_to_json(m)})
